import {Selection, NodeSelection, TextSelection} from "prosemirror-state"
import {dropPoint} from "prosemirror-transform"
import {Slice, Node} from "prosemirror-model"

import * as browser from "./browser"
import {captureKeyDown} from "./capturekeys"
import {parseFromClipboard, serializeForClipboard} from "./clipboard"
import {selectionBetween, selectionFromDOM} from "./selection"
import {keyEvent, DOMNode, textNodeBefore, textNodeAfter, isElt, isText} from "./dom"
import {focusPreventScroll} from "./domcoords"
import {EditorView} from "./index"
import {ViewDesc} from "./viewdesc"

// A collection of DOM events that occur within the editor, and callback functions
// to invoke when the event fires.
const handlers: {[event: string]: (view: EditorView, event: Event) => void} = {}
const editHandlers: {[event: string]: (view: EditorView, event: Event) => void} = {}
const passiveHandlers: Record<string, boolean> = {touchstart: true, touchmove: true}

export class InputState {
  shiftKey = false
  mouseDown: MouseDown | null = null
  lastKeyCode: number | null = null
  lastKeyCodeTime = 0
  lastKeyDispatched = false
  lastClick = {time: 0, x: 0, y: 0, type: "", button: 0}
  lastSelectionOrigin: string | null = null
  lastSelectionTime = 0
  lastIOSEnter = 0
  lastIOSEnterFallbackTimeout = -1
  lastFocus = 0
  lastTouch = 0
  lastChromeDelete = 0
  composing = false
  compositionNode: Text | null = null
  composingTimeout = -1
  compositionNodes: ViewDesc[] = []
  compositionEndedAt = -2e8
  compositionID = 1
  badSafariComposition = false
  // Set to a composition ID when there are pending changes at compositionend
  compositionPendingChanges = 0
  domChangeCount = 0
  eventHandlers: {[event: string]: (event: Event) => void} = Object.create(null)
  hideSelectionGuard: (() => void) | null = null
}

export function initInput(view: EditorView) {
  for (let event in handlers) {
    let handler = handlers[event]
    view.dom.addEventListener(event, view.input.eventHandlers[event] = (event: Event) => {
      if (!eventBelongsToView(view, event)) return
      if (view.input.composing && (event.type == "keydown" || event.type == "beforeinput") &&
          (event as KeyboardEvent).isComposing === false)
        leaveComposition(view, true)
      if (!runCustomHandler(view, event) && (view.editable || !(event.type in editHandlers)))
        handler(view, event)
    }, passiveHandlers[event] ? {passive: true} : undefined)
  }
  // On Safari, for reasons beyond my understanding, adding an input
  // event handler makes an issue where the composition vanishes when
  // you press enter go away.
  if (browser.safari) view.dom.addEventListener("input", () => null)

  ensureListeners(view)
}

function setSelectionOrigin(view: EditorView, origin: string) {
  view.input.lastSelectionOrigin = origin
  view.input.lastSelectionTime = Date.now()
}

export function destroyInput(view: EditorView) {
  if (view.input.mouseDown) view.input.mouseDown.done()
  view.domObserver.stop()
  for (let type in view.input.eventHandlers)
    view.dom.removeEventListener(type, view.input.eventHandlers[type])
  clearTimeout(view.input.composingTimeout)
  clearTimeout(view.input.lastIOSEnterFallbackTimeout)
}

export function ensureListeners(view: EditorView) {
  view.someProp("handleDOMEvents", currentHandlers => {
    for (let type in currentHandlers) if (!view.input.eventHandlers[type])
      view.dom.addEventListener(type, view.input.eventHandlers[type] = event => runCustomHandler(view, event))
  })
}

function runCustomHandler(view: EditorView, event: Event) {
  return view.someProp("handleDOMEvents", handlers => {
    let handler = handlers[event.type]
    return handler ? handler(view, event) || event.defaultPrevented : false
  })
}

function eventBelongsToView(view: EditorView, event: Event) {
  if (!event.bubbles) return true
  if (event.defaultPrevented) return false
  for (let node = event.target as DOMNode; node != view.dom; node = node.parentNode!)
    if (!node || node.nodeType == 11 ||
        (node.pmViewDesc && node.pmViewDesc.stopEvent(event)))
      return false
  return true
}

export function dispatchEvent(view: EditorView, event: Event) {
  if (!runCustomHandler(view, event) && handlers[event.type] &&
      (view.editable || !(event.type in editHandlers)))
    handlers[event.type](view, event)
}

export function dispatchKey(view: EditorView, event: KeyboardEvent | "Backspace" | "Enter") {
  let {input} = view
  if (input.lastKeyDispatched || view.composing) return false
  input.lastKeyDispatched = true
  if (typeof event == "string") event = keyEvent(event == "Backspace" ? 8 : 13, event)
  return view.someProp("handleKeyDown", f => f(view, event))
}

editHandlers.keydown = (view: EditorView, _event: Event) => {
  let event = _event as KeyboardEvent
  view.input.shiftKey = event.keyCode == 16 || event.shiftKey
  view.input.lastKeyCode = event.keyCode
  view.input.lastKeyCodeTime = Date.now()
  view.input.lastKeyDispatched = false
  // Suppress enter key events on Chrome Android, because those tend
  // to be part of a confused sequence of composition events fired,
  // and handling them eagerly tends to corrupt the input.
  if (browser.android && browser.chrome && event.keyCode == 13) return

  // On iOS, if we preventDefault enter key presses, the virtual
  // keyboard gets confused. So the hack here is to set a flag that
  // makes the DOM change code recognize that what just happens should
  // be replaced by whatever the Enter key handlers do.
  if (browser.ios && event.keyCode == 13 && !event.ctrlKey && !event.altKey && !event.metaKey) {
    let now = Date.now()
    view.input.lastIOSEnter = now
    view.input.lastIOSEnterFallbackTimeout = setTimeout(() => {
      if (view.input.lastIOSEnter == now) {
        dispatchKey(view, "Enter")
        view.input.lastIOSEnter = 0
      }
    }, 200)
    return
  }

  if (event.keyCode != 229) view.domObserver.forceFlush(true)
  if (dispatchKey(view, event) || captureKeyDown(view, event)) event.preventDefault()
  else setSelectionOrigin(view, "key")
}

editHandlers.keyup = (view, event) => {
  if ((event as KeyboardEvent).keyCode == 16) view.input.shiftKey = false
}

editHandlers.keypress = (view, _event) => {
  let event = _event as KeyboardEvent
  if (inOrNearComposition(view, event) || !event.charCode ||
      event.ctrlKey && !event.altKey || browser.mac && event.metaKey) return

  if (view.someProp("handleKeyPress", f => f(view, event))) {
    event.preventDefault()
    return
  }

  let sel = view.state.selection
  if (!(sel instanceof TextSelection) || !sel.$from.sameParent(sel.$to)) {
    let text = String.fromCharCode(event.charCode)
    let deflt = () => view.state.tr.insertText(text).scrollIntoView()
    if (!/[\r\n]/.test(text) && !view.someProp("handleTextInput", f => f(view, sel.$from.pos, sel.$to.pos, text, deflt)))
      view.dispatch(deflt())
    event.preventDefault()
  }
}

function eventCoords(event: MouseEvent) { return {left: event.clientX, top: event.clientY} }

function isNear(event: MouseEvent, click: {x: number, y: number}) {
  let dx = click.x - event.clientX, dy = click.y - event.clientY
  return dx * dx + dy * dy < 100
}

function runHandlerOnContext(
  view: EditorView,
  propName: "handleClickOn" | "handleDoubleClickOn" | "handleTripleClickOn",
  pos: number,
  inside: number,
  event: MouseEvent
) {
  if (inside == -1) return false
  let $pos = view.state.doc.resolve(inside)
  for (let i = $pos.depth + 1; i > 0; i--) {
    if (view.someProp(propName, f => i > $pos.depth ? f(view, pos, $pos.nodeAfter!, $pos.before(i), event, true)
                                                    : f(view, pos, $pos.node(i), $pos.before(i), event, false)))
      return true
  }
  return false
}

function updateSelection(view: EditorView, selection: Selection, origin: string) {
  if (!view.focused) view.focus()
  if (view.state.selection.eq(selection)) return
  let tr = view.state.tr.setSelection(selection)
  if (origin == "pointer") tr.setMeta("pointer", true)
  view.dispatch(tr)
}

function selectClickedLeaf(view: EditorView, inside: number) {
  if (inside == -1) return false
  let $pos = view.state.doc.resolve(inside), node = $pos.nodeAfter
  if (node && node.isAtom && NodeSelection.isSelectable(node)) {
    updateSelection(view, new NodeSelection($pos), "pointer")
    return true
  }
  return false
}

function selectClickedNode(view: EditorView, inside: number) {
  if (inside == -1) return false
  let sel = view.state.selection, selectedNode, selectAt
  if (sel instanceof NodeSelection) selectedNode = sel.node

  let $pos = view.state.doc.resolve(inside)
  for (let i = $pos.depth + 1; i > 0; i--) {
    let node = i > $pos.depth ? $pos.nodeAfter! : $pos.node(i)
    if (NodeSelection.isSelectable(node)) {
      if (selectedNode && sel.$from.depth > 0 &&
          i >= sel.$from.depth && $pos.before(sel.$from.depth + 1) == sel.$from.pos)
        selectAt = $pos.before(sel.$from.depth)
      else
        selectAt = $pos.before(i)
      break
    }
  }

  if (selectAt != null) {
    updateSelection(view, NodeSelection.create(view.state.doc, selectAt), "pointer")
    return true
  } else {
    return false
  }
}

function handleSingleClick(view: EditorView, pos: number, inside: number, event: MouseEvent, selectNode: boolean) {
  return runHandlerOnContext(view, "handleClickOn", pos, inside, event) ||
    view.someProp("handleClick", f => f(view, pos, event)) ||
    (selectNode ? selectClickedNode(view, inside) : selectClickedLeaf(view, inside))
}

function handleDoubleClick(view: EditorView, pos: number, inside: number, event: MouseEvent) {
  return runHandlerOnContext(view, "handleDoubleClickOn", pos, inside, event) ||
    view.someProp("handleDoubleClick", f => f(view, pos, event))
}

function handleTripleClick(view: EditorView, pos: number, inside: number, event: MouseEvent) {
  return runHandlerOnContext(view, "handleTripleClickOn", pos, inside, event) ||
    view.someProp("handleTripleClick", f => f(view, pos, event))
}

function selectionForTripleClick(doc: Node, inside: number, selectNodes: boolean): Selection | null {
  if (inside == -1) return doc.inlineContent ? TextSelection.create(doc, 0, doc.content.size) : null

  let $pos = doc.resolve(inside)
  for (let i = $pos.depth + 1; i > 0; i--) {
    let node = i > $pos.depth ? $pos.nodeAfter! : $pos.node(i)
    let nodePos = $pos.before(i)
    if (node.inlineContent)
      return TextSelection.create(doc, nodePos + 1, nodePos + 1 + node.content.size)
    else if (selectNodes && NodeSelection.isSelectable(node))
      return NodeSelection.create(doc, nodePos)
  }
  return null
}

let wordRE = /[\w_\u00a1-\uffff]+/g
try { wordRE = new RegExp("[\\p{L}\\p{N}_]+", "gu") } catch {}

function getWordAt(doc: Node, pos: number) {
  let $pos = doc.resolve(pos), parent = $pos.node()
  let context = "", from = pos, to = pos
  for (let i = $pos.indexAfter(), sawNonWS = false; i > 0; i--) {
    let prev = parent.child(i - 1)
    if (!prev.text) break
    let end = from == pos ? pos - $pos.posAtIndex(i - 1) : prev.text.length, start = end
    for (; start > 0; start--) {
      if (/\S/.test(prev.text[start - 1])) sawNonWS = true
      else if (sawNonWS) break
    }
    context = prev.text.slice(start, end) + context
    from -= end - start
    if (start || from < pos - 50) break
  }
  for (let i = $pos.index(), sawNonWS = false; i < parent.childCount; i++) {
    let next = parent.child(i)
    if (!next.text) break
    let start = to == pos ? pos - $pos.posAtIndex(i) : 0, end = start
    for (; end < next.text.length; end++) {
      if (/\S/.test(next.text[end])) sawNonWS = true
      else if (sawNonWS) break
    }
    context += next.text.slice(start, end)
    to += end - start
    if (end < next.text.length || to > pos + 50) break
  }

  let lastBefore = from, firstAfter = to
  if ((Intl as any).Segmenter) {
    for (let segment of new (Intl as any).Segmenter(undefined, {granularity: "word"}).segment(context)) {
      if (segment.isWordLike) {
        let start = segment.index + from, end = start + segment.segment.length
        if (end < pos) lastBefore = end
        else if (start > pos) { firstAfter = start; break }
        else return TextSelection.create(doc, start, end)
      }
    }
  } else {
    wordRE.lastIndex = 0
    for (let m; m = wordRE.exec(context);) {
      let start = m.index + from, end = start + m[0].length
      if (end < pos) lastBefore = end
      else if (start > pos) { firstAfter = start; break }
      else return TextSelection.create(doc, start, end)
    }
  }

  let before = context.slice(lastBefore - from, pos - from), after = context.slice(pos - from, firstAfter - from)
  let nonSpaceBefore = /\S*$/.exec(before)![0].length, nonSpaceAfter = /^\S*/.exec(after)![0].length
  if (nonSpaceBefore || nonSpaceAfter)
    return TextSelection.create(doc, pos - nonSpaceBefore, pos + nonSpaceAfter)
  let spaceBefore = /\s*$/.exec(before)![0].length, spaceAfter = /^\s*/.exec(after)![0].length
  return TextSelection.create(doc, pos - spaceBefore, pos + spaceAfter)
}

const selectNodeModifier: keyof MouseEvent = browser.mac ? "metaKey" : "ctrlKey"

handlers.mousedown = (view, _event) => {
  let event = _event as MouseEvent, now = Date.now()
  view.input.shiftKey = event.shiftKey
  if (view.input.lastTouch > now - 500) return false // Ignore touch interaction
  endComposition(view)

  let type = "singleClick"
  if (now - view.input.lastClick.time < 500 && isNear(event, view.input.lastClick) && !event[selectNodeModifier] &&
      view.input.lastClick.button == event.button) {
    if (view.input.lastClick.type == "singleClick") type = "doubleClick"
    else if (view.input.lastClick.type == "doubleClick") type = "tripleClick"
  }
  view.input.lastClick = {time: now, x: event.clientX, y: event.clientY, type, button: event.button}

  if (view.input.mouseDown) view.input.mouseDown.done()

  let pos = view.posAtCoords(eventCoords(event))
  if (!pos) return

  if (event.button == 0) {
    if (!view.hasFocus()) {
      focusPreventScroll(view.dom)
      let active = view.root.activeElement
      if (active && !active.contains(view.dom)) (active as HTMLElement).blur()
    }
    let mouseDown = view.input.mouseDown = new MouseDown(view, pos, event, type)
    if (!mouseDown.mightDrag) event.preventDefault()
  } else {
    setSelectionOrigin(view, "pointer")
  }
}

class MouseDown {
  startDoc: Node
  // If, on normal click, we should try to select a node
  selectNode: boolean
  // True if this is a shift selection
  extend: boolean
  // Information about the node that this may drag
  mightDrag: {node: Node, elt: Element | undefined, pos: number, addAttr: boolean} | boolean
  didMove = false
  lastPos: number = -1

  // Anchor for the selection. With shift held, this will be the
  // original start selection. Otherwise, it'll be the selection
  // created for the initial position.
  anchorRange: {from: number, to: number} | null = null
  // If the document changes during selection, we try to reconstruct
  // an anchor from the (document-relative) coordinates of the old
  // one.
  anchorDoc: Node
  anchorOffset: {x: number, y: number}

  constructor(
    readonly view: EditorView,
    readonly startPos: {pos: number, inside: number},
    readonly event: MouseEvent,
    readonly type: string // single/double/tripleClick
  ) {
    this.startDoc = view.state.doc
    this.selectNode = !!event[selectNodeModifier]
    this.extend = event.shiftKey

    this.anchorDoc = this.startDoc
    let startBase = docBase(view)
    if (this.extend) {
      let sel = view.state.selection
      this.anchorRange = sel instanceof NodeSelection ? {from: sel.from, to: sel.to} : {from: sel.anchor, to: sel.anchor}
      let rect = sel instanceof NodeSelection ? (view.nodeDOM(sel.from) as HTMLElement).getBoundingClientRect()
        : view.coordsAtPos(sel.anchor)
      this.anchorOffset = {x: (rect.left + rect.right) / 2 - startBase.x,
                           y: (rect.top + rect.bottom) / 2 - startBase.y}
    } else {
      this.anchorOffset = {x: event.clientX - startBase.x, y: event.clientY - startBase.y}
    }

    if (type == "singleClick") {
      let {selection} = view.state
      let targetNode: Node, targetPos, targetSelected = false

      if (selection instanceof NodeSelection && selection.from <= startPos.pos && selection.to >= startPos.pos) {
        targetPos = selection.from
        targetNode = selection.node
        targetSelected = true
      } else if (startPos.inside > -1) {
        targetNode = view.state.doc.nodeAt(startPos.inside)!
        targetPos = startPos.inside
      } else {
        let $pos = view.state.doc.resolve(startPos.pos)
        targetNode = $pos.parent
        targetPos = $pos.depth ? $pos.before() : -1
      }

      if (targetSelected || targetPos > -1 && targetNode.type.spec.draggable && targetNode.type.spec.selectable !== false) {
        let elt = view.docView.descAt(targetPos)?.nodeDOM as HTMLElement | undefined
        this.mightDrag = {
          node: targetNode,
          elt,
          pos: targetPos,
          addAttr: false
        }
        if (elt && !elt.draggable) {
          this.mightDrag.addAttr = true
          view.domObserver.stopped(() => elt.draggable = true)
        }
      } else {
        this.mightDrag = isInSelection(view, event)
      }
    } else {
      this.mightDrag = false
    }

    view.root.addEventListener("mouseup", this.up = this.up.bind(this) as any)
    view.root.addEventListener("mousemove", this.move = this.move.bind(this) as any)

    if (!this.mightDrag) this.select(this.startPos, true)
  }

  done() {
    this.view.root.removeEventListener("mouseup", this.up as any)
    this.view.root.removeEventListener("mousemove", this.move as any)
    if (this.view.input.mouseDown == this) this.view.input.mouseDown = null
    if (typeof this.mightDrag == "object" && this.mightDrag.addAttr) {
      this.view.domObserver.stopped(() => (this.mightDrag as any).elt.removeAttribute("draggable"))
    }
  }

  maybeRunHandler(pos: {pos: number, inside: number}, event: MouseEvent) {
    let handler = this.type == "singleClick" ? handleSingleClick
      : this.type == "doubleClick" ? handleDoubleClick : handleTripleClick
    return handler(this.view, pos.pos, pos.inside, event, this.selectNode)
  }

  up(event: MouseEvent) {
    this.done()

    if (!this.view.dom.contains(event.target as HTMLElement)) return

    let pos: {pos: number, inside: number} | null = this.startPos
    if (this.view.state.doc != this.startDoc) pos = this.view.posAtCoords(eventCoords(event))
    if (!pos) return

    if (!this.didMove) {
      this.maybeRunHandler(pos, event) || this.select(pos, true)
    }
    event.preventDefault()
  }

  move(event: MouseEvent) {
    if (event.buttons == 0) {
      this.done()
      return
    }
    if (!this.didMove &&
        (Math.abs(this.event.x - event.clientX) > 8 || Math.abs(this.event.y - event.clientY) > 8)) {
      this.didMove = true
      this.mightDrag = false
    }
    if (!this.mightDrag) {
      let pos = this.view.posAtCoords(eventCoords(event))
      if (pos) this.select(pos, false)
    }
    event.preventDefault()
  }

  select(pos: {pos: number, inside: number}, first: boolean) {
    if (pos.pos == this.lastPos) return
    this.lastPos = pos.pos

    let {view} = this, {doc} = view.state
    let selection = this.type == "singleClick" ? clickedRange(view, doc, pos)
      : this.type == "doubleClick" ? getWordAt(doc, pos.pos)
      : selectionForTripleClick(doc, pos.inside, first)
    if (!selection) return

    if (first && !this.extend) {
      this.anchorRange = selection
    } else if (!first || this.extend) {
      if (!doc.eq(this.anchorDoc)) this.restoreAnchor()
      if (this.anchorRange && this.anchorRange.from < selection.from)
        selection = selectionBetween(view, doc.resolve(this.anchorRange.from), doc.resolve(selection.to))
      else if (this.anchorRange && this.anchorRange.to > selection.to)
        selection = selectionBetween(view, doc.resolve(this.anchorRange.to), doc.resolve(selection.from))
    }

    if (!selection.eq(view.state.selection))
      view.dispatch(view.state.tr.setSelection(selection).setMeta("pointer", true).scrollIntoView())
  }

  restoreAnchor() {
    let base = docBase(this.view)
    let pos = this.view.posAtCoords({left: this.anchorOffset.x + base.x, top: this.anchorOffset.y + base.y})
    if (!pos) {
      this.anchorRange = null
    } else {
      let {doc} = this.view.state
      this.anchorRange = this.type == "singleClick" ? clickedRange(this.view, doc, pos)
        : this.type == "doubleClick" ? getWordAt(doc, pos.pos)
        : selectionForTripleClick(doc, pos.inside, false)
      this.anchorDoc = this.view.state.doc
    }
  }
}

function docBase(view: EditorView) {
  let rect = view.dom.getBoundingClientRect()
  return {x: rect.left - view.dom.scrollLeft, y: rect.top - view.dom.scrollTop}
}

function clickedRange(view: EditorView, doc: Node, pos: {pos: number, inside: number}) {
  if (pos.inside > -1) {
    let target = doc.nodeAt(pos.inside)!
    if (target.isAtom && NodeSelection.isSelectable(target))
      return NodeSelection.create(doc, pos.inside)
  }
  let $pos = doc.resolve(pos.pos)
  return selectionBetween(view, $pos, $pos)
}

function isInSelection(view: EditorView, event: MouseEvent) {
  let {selection} = view.state
  if (selection.empty) return false
  let sel = view.domSelection()
  if (!sel || sel.rangeCount == 0) return true
  let rects = sel.getRangeAt(0).getClientRects()
  for (let i = 0; i < rects.length; i++) {
    let rect = rects[i]
    if (rect.left <= event.clientX && rect.right >= event.clientX &&
      rect.top <= event.clientY && rect.bottom >= event.clientY) return true
  }
  return false
}

handlers.touchstart = view => {
  view.input.lastTouch = Date.now()
  endComposition(view)
  setSelectionOrigin(view, "pointer")
}

handlers.touchmove = view => {
  view.input.lastTouch = Date.now()
  setSelectionOrigin(view, "pointer")
}

handlers.contextmenu = view => endComposition(view)

function inOrNearComposition(view: EditorView, event: Event) {
  if (view.composing) return true
  // See https://www.stum.de/2016/06/24/handling-ime-events-in-javascript/.
  // On Japanese input method editors (IMEs), the Enter key is used to confirm character
  // selection. On Safari, when Enter is pressed, compositionend and keydown events are
  // emitted. The keydown event triggers newline insertion, which we don't want.
  // This method returns true if the keydown event should be ignored.
  // We only ignore it once, as pressing Enter a second time *should* insert a newline.
  // Furthermore, the keydown event timestamp must be close to the compositionEndedAt timestamp.
  // This guards against the case where compositionend is triggered without the keyboard
  // (e.g. character confirmation may be done with the mouse), and keydown is triggered
  // afterwards- we wouldn't want to ignore the keydown event in this case.
  if (browser.safari && Math.abs(Date.now() - view.input.compositionEndedAt) < 500) {
    view.input.compositionEndedAt = -2e8
    return true
  }
  return false
}

// Drop active composition after 5 seconds of inactivity on Android
const timeoutComposition = browser.android ? 5000 : -1

editHandlers.compositionstart = editHandlers.compositionupdate = view => {
  if (!view.composing) {
    view.domObserver.flush()
    let {state} = view, $pos = state.selection.$to
    if (state.selection instanceof TextSelection && state.selection.empty &&
        (state.storedMarks ||
         (!$pos.textOffset && $pos.parentOffset && $pos.nodeBefore!.marks.some(m => m.type.spec.inclusive === false)) ||
         browser.chrome && browser.windows && selectionBeforeUneditable(view))) { // Issue #1500
      // Need to wrap the cursor in mark nodes different from the ones in the DOM context
      view.markCursor = view.state.storedMarks || $pos.marks()
      endComposition(view, true)
      view.markCursor = null
    } else {
      endComposition(view, !state.selection.empty)
      // In firefox, if the cursor is after but outside a marked node,
      // the inserted text won't inherit the marks. So this moves it
      // inside if necessary.
      if (browser.gecko && view.domSel.active && state.selection.empty &&
          $pos.parentOffset && !$pos.textOffset && $pos.nodeBefore!.marks.length) {
        for (let {focusNode: node, focusOffset: offset} = view.domSel.range; node && isElt(node) && offset != 0;) {
          let before = offset < 0 ? node.lastChild : node.childNodes[offset - 1]
          if (!before) break
          if (isText(before)) {
            let sel = view.domSelection()
            if (sel) sel.collapse(before, before.nodeValue!.length)
            break
          } else {
            node = before
            offset = -1
          }
        }
      }
    }
    view.input.composing = true
  }
  scheduleComposeEnd(view, timeoutComposition)
}

function selectionBeforeUneditable(view: EditorView) {
  let {focusNode, focusOffset} = view.domSel.range
  if (!focusNode || !isElt(focusNode) || focusOffset >= focusNode.childNodes.length) return false
  let next = focusNode.childNodes[focusOffset]
  return isElt(next) && next.contentEditable == "false"
}

editHandlers.compositionend = (view, event) => {
  if (view.composing) leaveComposition(view)
}

function leaveComposition(view: EditorView, sync = false) {
  view.input.composing = false
  view.input.compositionEndedAt = Date.now()
  view.input.compositionPendingChanges = view.domObserver.pendingRecords().length ? view.input.compositionID : 0
  view.input.compositionNode = null
  if (view.input.badSafariComposition) view.domObserver.forceFlush()
  else if (view.input.compositionPendingChanges) Promise.resolve().then(() => view.domObserver.flush())
  view.input.compositionID++
  if (sync) endComposition(view)
  else scheduleComposeEnd(view, 20)
}

function scheduleComposeEnd(view: EditorView, delay: number) {
  clearTimeout(view.input.composingTimeout)
  if (delay > -1) view.input.composingTimeout = setTimeout(() => endComposition(view), delay)
}

export function clearComposition(view: EditorView) {
  if (view.composing) {
    view.input.composing = false
    view.input.compositionEndedAt = Date.now()
  }
  for (let node; node = view.input.compositionNodes.pop();)
    node.markParentDamage()
}

export function findCompositionNode(view: EditorView) {
  let sel = view.domSel.range
  if (!view.domSel.active || !sel.focusNode) return null
  let textBefore = textNodeBefore(sel.focusNode, sel.focusOffset)
  let textAfter = textNodeAfter(sel.focusNode, sel.focusOffset)
  if (textBefore && textAfter && textBefore != textAfter) {
    let descAfter = textAfter.pmViewDesc, lastChanged = view.domObserver.lastChangedTextNode
    if (textBefore == lastChanged || textAfter == lastChanged) return lastChanged
    if (!descAfter || !descAfter.isText(textAfter.nodeValue!)) {
      return textAfter
    } else if (view.input.compositionNode == textAfter) {
      let descBefore = textBefore.pmViewDesc
      if (!(!descBefore || !descBefore.isText(textBefore.nodeValue!)))
        return textAfter
    }
  }
  return textBefore || textAfter
}

/// @internal
export function endComposition(view: EditorView, restarting = false) {
  if (browser.android && view.domObserver.flushingSoon >= 0) return
  view.domObserver.forceFlush()
  clearComposition(view)
  if (restarting || view.docView && view.docView.damage) {
    let sel = selectionFromDOM(view, view.domSel.readRange()), cur = view.state.selection
    if (sel && !sel.eq(cur))
      view.dispatch(view.state.tr.setSelection(sel))
    else if ((view.markCursor || restarting) && !cur.$from.node(cur.$from.sharedDepth(cur.to)).inlineContent)
      view.dispatch(view.state.tr.deleteSelection())
    else
      view.updateState(view.state)
  }
}

function captureCopy(view: EditorView, dom: HTMLElement) {
  // The extra wrapper is somehow necessary on IE/Edge to prevent the
  // content from being mangled when it is put onto the clipboard
  if (!view.dom.parentNode) return
  let wrap = view.dom.parentNode.appendChild(document.createElement("div"))
  wrap.appendChild(dom)
  wrap.style.cssText = "position: fixed; left: -10000px; top: 10px"
  let sel = getSelection()!, range = document.createRange()
  range.selectNodeContents(dom)
  // Done because IE will fire a selectionchange moving the selection
  // to its start when removeAllRanges is called and the editor still
  // has focus (which will mess up the editor's selection state).
  view.dom.blur()
  sel.removeAllRanges()
  sel.addRange(range)
  setTimeout(() => {
    if (wrap.parentNode) wrap.parentNode.removeChild(wrap)
    view.focus()
  }, 50)
}

// This is very crude, but unfortunately old iOS Safari versions
// _pretend_ that they have a clipboard API—all the objects and
// methods are there, they just don't work, and they are hard to test.
const brokenClipboardAPI = browser.ios && browser.webkit_version < 604

handlers.copy = editHandlers.cut = (view, _event) => {
  let event = _event as ClipboardEvent
  let sel = view.state.selection, cut = event.type == "cut"
  if (sel.empty) return

  // IE and Edge's clipboard interface is completely broken
  let data = brokenClipboardAPI ? null : event.clipboardData
  let slice = sel.content(), {dom, text} = serializeForClipboard(view, slice)
  if (data) {
    event.preventDefault()
    data.clearData()
    data.setData("text/html", dom.innerHTML)
    data.setData("text/plain", text)
  } else {
    captureCopy(view, dom)
  }
  if (cut) view.dispatch(view.state.tr.deleteSelection().scrollIntoView().setMeta("uiEvent", "cut"))
}

function sliceSingleNode(slice: Slice) {
  return slice.openStart == 0 && slice.openEnd == 0 && slice.content.childCount == 1 ? slice.content.firstChild : null
}

function capturePaste(view: EditorView, event: ClipboardEvent) {
  if (!view.dom.parentNode) return
  let plainText = view.input.shiftKey || view.state.selection.$from.parent.type.spec.code
  let target = view.dom.parentNode.appendChild(document.createElement(plainText ? "textarea" : "div"))
  if (!plainText) target.contentEditable = "true"
  target.style.cssText = "position: fixed; left: -10000px; top: 10px"
  target.focus()
  let plain = view.input.shiftKey && view.input.lastKeyCode != 45
  setTimeout(() => {
    view.focus()
    if (target.parentNode) target.parentNode.removeChild(target)
    if (plainText) doPaste(view, (target as HTMLTextAreaElement).value, null, plain, event)
    else doPaste(view, target.textContent!, target.innerHTML, plain, event)
  }, 50)
}

export function doPaste(view: EditorView, text: string, html: string | null, preferPlain: boolean, event: ClipboardEvent) {
  let slice = parseFromClipboard(view, text, html, preferPlain, view.state.selection.$from)
  if (view.someProp("handlePaste", f => f(view, event, slice || Slice.empty))) return true
  if (!slice) return false

  let singleNode = sliceSingleNode(slice)
  let tr = singleNode
    ? view.state.tr.replaceSelectionWith(singleNode, preferPlain)
    : view.state.tr.replaceSelection(slice)
  view.dispatch(tr.scrollIntoView().setMeta("paste", true).setMeta("uiEvent", "paste"))
  return true
}

function getText(clipboardData: DataTransfer) {
  let text = clipboardData.getData("text/plain") || clipboardData.getData("Text")
  if (text) return text
  let uris = clipboardData.getData("text/uri-list")
  return uris ? uris.replace(/\r?\n/g, " ") : ""
}

editHandlers.paste = (view, _event) => {
  let event = _event as ClipboardEvent
  // Handling paste from JavaScript during composition is very poorly
  // handled by browsers, so as a dodgy but preferable kludge, we just
  // let the browser do its native thing there, except on Android,
  // where the editor is almost always composing.
  if (view.composing && !browser.android) return
  let data = brokenClipboardAPI ? null : event.clipboardData
  let plain = view.input.shiftKey && view.input.lastKeyCode != 45
  if (data && doPaste(view, getText(data), data.getData("text/html"), plain, event))
    event.preventDefault()
  else
    capturePaste(view, event)
}

export class Dragging {
  constructor(readonly slice: Slice, readonly move: boolean, readonly node?: NodeSelection) {}
}

const dragCopyModifier: keyof DragEvent = browser.mac ? "altKey" : "ctrlKey"

function dragMoves(view: EditorView, event: DragEvent) {
  let copy: boolean | undefined
  view.someProp("dragCopies", test => { copy = copy || test(event) })
  return copy != null ? !copy : !event[dragCopyModifier]
}

handlers.dragstart = (view, _event) => {
  let event = _event as DragEvent
  let mouseDown = view.input.mouseDown
  if (mouseDown) mouseDown.done()
  if (!event.dataTransfer) return

  let sel = view.state.selection
  let pos = sel.empty ? null : view.posAtCoords(eventCoords(event))
  let node: undefined | NodeSelection
  if (pos && pos.pos >= sel.from && pos.pos <= (sel instanceof NodeSelection ? sel.to - 1: sel.to)) {
    // In selection
  } else if (mouseDown && typeof mouseDown.mightDrag == "object") {
    node = NodeSelection.create(view.state.doc, mouseDown.mightDrag.pos)
  } else if (event.target && isElt(event.target as HTMLElement)) {
    let desc = view.docView.nearestDesc(event.target as HTMLElement, true)
    if (desc && desc.node.type.spec.draggable && desc != view.docView)
      node = NodeSelection.create(view.state.doc, desc.posBefore)
  }
  let draggedSlice = (node || view.state.selection).content()
  let {dom, text, slice} = serializeForClipboard(view, draggedSlice)
  // Pre-120 Chrome versions clear files when calling `clearData` (#1472)
  if (!event.dataTransfer.files.length || !browser.chrome || browser.chrome_version > 120)
    event.dataTransfer.clearData()
  event.dataTransfer.setData(brokenClipboardAPI ? "Text" : "text/html", dom.innerHTML)
  // See https://code.haverbeke.berlin/prosemirror/prosemirror/issues/1156
  event.dataTransfer.effectAllowed = "copyMove"
  if (!brokenClipboardAPI) event.dataTransfer.setData("text/plain", text)
  view.dragging = new Dragging(slice, dragMoves(view, event), node)
}

handlers.dragend = view => {
  let dragging = view.dragging
  window.setTimeout(() => {
    if (view.dragging == dragging)  view.dragging = null
  }, 50)
}

editHandlers.dragover = editHandlers.dragenter = (_, e) => e.preventDefault()

editHandlers.drop = (view, event) => {
  try {
    handleDrop(view, event as DragEvent, view.dragging)
  } finally {
    view.dragging = null
  }
}

function handleDrop(view: EditorView, event: DragEvent, dragging: Dragging | null) {
  if (!event.dataTransfer) return

  let eventPos = view.posAtCoords(eventCoords(event))
  if (!eventPos) return
  let $mouse = view.state.doc.resolve(eventPos.pos)
  let slice = dragging && dragging.slice
  if (slice) {
    view.someProp("transformPasted", f => { slice = f(slice!, view, false) })
  } else {
    slice = parseFromClipboard(view, getText(event.dataTransfer),
                               brokenClipboardAPI ? null : event.dataTransfer.getData("text/html"), false, $mouse)
  }
  let move = !!(dragging && dragMoves(view, event))
  if (view.someProp("handleDrop", f => f(view, event, slice || Slice.empty, move))) {
    event.preventDefault()
    return
  }
  if (!slice) return

  event.preventDefault()
  let insertPos = slice ? dropPoint(view.state.doc, $mouse.pos, slice) : $mouse.pos
  if (insertPos == null) insertPos = $mouse.pos

  let tr = view.state.tr
  if (move) {
    let {node} = dragging as Dragging
    if (node) node.replace(tr)
    else tr.deleteSelection()
  }

  let pos = tr.mapping.map(insertPos)
  let isNode = slice.openStart == 0 && slice.openEnd == 0 && slice.content.childCount == 1
  let beforeInsert = tr.doc
  if (isNode)
    tr.replaceRangeWith(pos, pos, slice.content.firstChild!)
  else
    tr.replaceRange(pos, pos, slice)
  if (tr.doc.eq(beforeInsert)) return

  let $pos = tr.doc.resolve(pos)
  if (isNode && NodeSelection.isSelectable(slice.content.firstChild!) &&
      $pos.nodeAfter && $pos.nodeAfter.sameMarkup(slice.content.firstChild!)) {
    tr.setSelection(new NodeSelection($pos))
  } else {
    let end = tr.mapping.map(insertPos)
    tr.mapping.maps[tr.mapping.maps.length - 1].forEach((_from, _to, _newFrom, newTo) => end = newTo)
    tr.setSelection(selectionBetween(view, $pos, tr.doc.resolve(end)))
  }
  view.focus()
  view.dispatch(tr.setMeta("uiEvent", "drop"))
}

handlers.focus = view => {
  view.input.lastFocus = Date.now()
  if (!view.focused) {
    view.domObserver.stopped(() => view.dom.classList.add("ProseMirror-focused"))
    view.focused = true
    view.domSel.read()
    if (!view.domSel.synced) {
      let startSel = view.domSel.range
      setTimeout(() => {
        let curSel = view.domSel.readRange()
        if (curSel && startSel.eq(curSel)) view.domSel.sync()
      }, 20)
    }
  }
}

handlers.blur = (view, _event) => {
  let event = _event as FocusEvent
  if (view.focused) {
    view.domObserver.stopped(() => view.dom.classList.remove("ProseMirror-focused"))
    if (event.relatedTarget && view.dom.contains(event.relatedTarget as HTMLElement))
      view.domSel.deactivate()
    view.focused = false
  }
}

handlers.beforeinput = (view, _event: Event) => {
  let event = _event as InputEvent
  // We should probably do more with beforeinput events, but support
  // is so spotty that I'm still waiting to see where they are going.

  // Very specific hack to deal with backspace sometimes failing on
  // Chrome and Firefox Android when after an uneditable node.
  if (browser.android && event.inputType == "deleteContentBackward") {
    view.domObserver.flushSoon()
    let {domChangeCount} = view.input
    setTimeout(() => {
      if (view.input.domChangeCount != domChangeCount || view.domObserver.pendingRecords().length)
        return // Event already had some effect
      // This bug tends to close the virtual keyboard, so we refocus
      view.dom.blur()
      view.focus()
      if (dispatchKey(view, "Backspace")) return
      let {$cursor} = view.state.selection as TextSelection
      // Crude approximation of backspace behavior when no command handled it
      if ($cursor && $cursor.pos > 0) view.dispatch(view.state.tr.delete($cursor.pos - 1, $cursor.pos).scrollIntoView())
    }, 50)
  }
}

// Make sure all handlers get registered
for (let prop in editHandlers) handlers[prop] = editHandlers[prop]
